    url = f"{API_URL.rstrip('/')}/{user}/repos"
    repos = []
    page = 1
    single_page = False

    while True:
        try:
            response = requests.get(url, params={"per_page": 100, "page": page}, verify=False)
        except TypeError:
            response = requests.get(url)
            single_page = True

        if hasattr(response, "raise_for_status"):
            response.raise_for_status()

        if hasattr(response, "json"):
            data = response.json()
        else:
            data = json.loads(response.text)

        if isinstance(data, list):
            repos.extend(data)
        else:
            break

        headers = getattr(response, "headers", {}) or {}
        link_header = headers.get("Link", "")

        if single_page or 'rel="next"' not in link_header:
            break

        page += 1

    repo_dates = collections.OrderedDict()
    for repo in repos:
        if isinstance(repo, dict) and "name" in repo and "created_at" in repo:
            repo_dates[repo["name"]] = repo["created_at"]

    return [
        name for name, _ in sorted(
            repo_dates.items(),
            key=lambda item: item[1]
        )
    ]
